package com.bank.oncall;

import java.util.Map;
import java.util.logging.Logger;

// PagerDuty/Opsgenie-style: page primary, escalate to secondary, link runbook,
// open comms channel.
public class AlertRouter {
    private static final Logger log = Logger.getLogger(AlertRouter.class.getName());
    private final OnCallSchedule schedule;
    private final Map<String, Runbook> runbooks;

    public AlertRouter(OnCallSchedule schedule, Map<String, Runbook> runbooks) {
        this.schedule = schedule;
        this.runbooks = runbooks;
    }

    public void handleAlert(String alertType, String summary) {
        log.severe(() -> "ALERT [" + alertType + "]: " + summary
            + " (on-call week " + schedule.getWeek() + ")");

        // Page primary first.
        Responder primary = schedule.getPrimary();
        log.info(() -> "Paging PRIMARY " + primary.getName() + " via PagerDuty...");
        Responder responder;
        if (primary.acknowledges()) {
            log.info(() -> primary.getName() + " ACKNOWLEDGED.");
            responder = primary;
        } else {
            // Escalation policy: timeout → secondary.
            Responder secondary = schedule.getSecondary();
            log.warning(() -> primary.getName() + " did NOT ack in time — ESCALATING to SECONDARY "
                + secondary.getName());
            log.info(() -> secondary.getName() + " ACKNOWLEDGED.");
            responder = secondary;
        }

        // Open comms channel (Slack/Teams).
        String channel = "#inc-" + alertType;
        final Responder resp = responder;
        log.info(() -> "Opened " + channel + " (Slack); " + resp.getName() + " is incident lead.");

        // Link the runbook.
        Runbook rb = runbooks.get(alertType);
        if (rb != null) {
            log.info(() -> "Runbook for '" + alertType + "' attached — first steps:");
            int n = 1;
            for (String step : rb.getSteps()) {
                final int num = n++;
                log.info(() -> "    " + num + ". " + step);
            }
        } else {
            log.warning(() -> "No runbook for '" + alertType + "' — add one after this incident.");
        }
    }
}
