package com.bank.oncall;

import java.util.List;
import java.util.Map;
import java.util.logging.*;

public class OnCallDemo {
    private static final Logger log = Logger.getLogger(OnCallDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // Primary is unreachable (asleep) → escalation to secondary demonstrated.
        Responder rajesh = new Responder("Rajesh (primary)", false);
        Responder priya  = new Responder("Priya (secondary)", true);
        OnCallSchedule schedule = new OnCallSchedule("2026-W44", rajesh, priya);

        Runbook transferRunbook = new Runbook("transfer-5xx", List.of(
            "Confirm impact on Grafana Transfer SLO dashboard",
            "Check what changed: kubectl rollout history transfer-service",
            "MITIGATE FIRST: kubectl rollout undo (rollback)",
            "Post status every 5 min in #inc-transfer-5xx",
            "After restore: open blameless postmortem"));

        AlertRouter router = new AlertRouter(schedule, Map.of("transfer-5xx", transferRunbook));
        router.handleAlert("transfer-5xx", "transfer-api 5xx error rate at 40%");
    }
}
